using System;

namespace AnimalTown;

public enum WaterRenderStyle { WindWaker, Sunshine }

// Only the *authored* mip chain goes onto GX. It is NOT generated by reducing
// the base level: the 64px and 4px levels are transparent, the 32px level
// carries water caustics, and the 16px level is a brighter fake sky-reflection
// band. The source art lives in assets/textures/environment/water/ and is
// imported into a native DNTX package by SunshineWaterAssets during ISO cook.
public static class SunshineWater
{
    public const int TextureSize=64,MipLevels=5,PayloadBytes=10912;
    public const float RiverBedDepth=.40f,SeaBedDepth=.75f;
    public const string DiscTexture="dvd:/sunshine-water.dndtex";
    // A positive hardware LOD bias brings the strong 16px reflection band
    // inside the curved AnimalTown camera's visible sea, without LOD shells.
    public const float LodBias=.65f;
    // Exact GX byte references: retain low alpha or strong glints and reject
    // the middle band after both texture samples have contributed to opacity.
    public const byte GlintLowReference=33,GlintHighReference=235;

    public static int Edge(int level)
    {
        if((uint)level>=MipLevels)throw new ArgumentOutOfRangeException(nameof(level));
        return TextureSize>>level;
    }

    // Readability-only alpha map derived at cook time from the authored
    // grayscale. The actual source art is editable and each mip independent.
    // No per-frame CPU evaluation or texture regeneration is performed.
    public static byte AlphaForLuma(int level,byte value)
    {
        if((uint)level>=MipLevels)throw new ArgumentOutOfRangeException(nameof(level));
        int a=level switch {
            0 or 4 => 0,
            // L1 needs enough near-wave glints to survive the >=235 branch.
            1 => (int)Math.Round(Math.Max(0,value-12)*1.55),
            2 => (int)Math.Round(Math.Max(0,value-35)*1.31),
            _ => (int)Math.Round(value*.72)
        };
        return (byte)Math.Min(255,a);
    }

    // Input is five row-major, artist-authored grayscale arrays, NOT mips
    // generated by a conventional downsampler. GX IA8 packs alpha then
    // luminance, 16 pixels per 4x4 tile, in big-endian-native block order.
    public static byte[] PackLevels(byte[][] levelPixels)
    {
        if(levelPixels==null||levelPixels.Length!=MipLevels)throw new ArgumentException("Expected five authored mip levels.");
        var data=new byte[32+PayloadBytes];int at=32;
        Put(data,0,0x58544e44);  // DNTX
        Put(data,4,2);           // Version 2: explicit mip chain
        Put(data,8,3);           // GX IA8 (A,I)
        Put(data,12,TextureSize);Put(data,16,TextureSize);
        Put(data,20,PayloadBytes);Put(data,24,MipLevels);
        for(int level=0;level<MipLevels;level++){
            int size=Edge(level);
            var pixels=levelPixels[level];
            if(pixels==null||pixels.Length!=size*size)
                throw new ArgumentException("Incorrect authored mip dimensions: "+level);
            for(int by=0;by<size;by+=4)for(int bx=0;bx<size;bx+=4)
                for(int y=by;y<by+4;y++)for(int x=bx;x<bx+4;x++){
                    byte lum=pixels[y*size+x];
                    data[at++]=AlphaForLuma(level,lum);
                    data[at++]=lum;
                }
        }
        if(at!=data.Length)throw new InvalidOperationException("Invalid Sunshine mip payload size.");
        return data;
    }

    public static void ValidatePackage(byte[] data)
    {
        if(data==null||data.Length!=32+PayloadBytes||
           TexturePixels.Int(data,0)!=0x58544e44||TexturePixels.Int(data,4)!=2||
           TexturePixels.Int(data,8)!=3||TexturePixels.Int(data,12)!=TextureSize||
           TexturePixels.Int(data,16)!=TextureSize||TexturePixels.Int(data,20)!=PayloadBytes||
           TexturePixels.Int(data,24)!=MipLevels||TexturePixels.Int(data,28)!=0)
            throw new InvalidOperationException("Invalid authored Sunshine GX mip package.");
        int at=32;int[] mean=new int[MipLevels];
        for(int level=0;level<MipLevels;level++){
            int size=Edge(level),total=0,bright=0;
            for(int pixel=0;pixel<size*size;pixel++){
                int alpha=data[at++],lum=data[at++];
                if(alpha!=AlphaForLuma(level,(byte)lum))
                    throw new InvalidOperationException("Sunshine mip alpha does not match authored image.");
                if((level==0||level==4)&&(lum!=0||alpha!=0))
                    throw new InvalidOperationException("Near/far Sunshine levels must be fully clear.");
                total+=lum;
                if(alpha>=GlintHighReference)bright++;
            }
            mean[level]=total/(size*size);
            if(level==1&&bright<64||level==2&&bright<24)
                throw new InvalidOperationException("Insufficient caustic/reflection coverage.");
        }
        if(at!=data.Length||!(mean[0]==0&&mean[1]>50&&mean[2]>mean[1]+15&&
           mean[2]>mean[3]*2&&mean[4]==0))
            throw new InvalidOperationException("Sunshine mip levels are not independently authored.");
    }

    // Sunshine's separate small near-field wave overlay uses just two sine
    // components and fades at its edges. The GPU handles all fine caustics.
    public static float LocalWaveHeight(int x,int z,float worldX,float worldZ,double seconds)
    {
        float fade=WindWakerWaveField.EdgeWeight(x,z);
        double tA=Math.IEEERemainder(seconds*1.13,2*Math.PI);
        double tB=Math.IEEERemainder(seconds*.86,2*Math.PI);
        return .047f+fade*(.024f*(float)Math.Sin(worldX*1.75+tA)+
                             .015f*(float)Math.Sin(worldZ*1.42+tB));
    }

    // Reproject the *existing* sea and river meshes inward on the world
    // cylinder rather than allocating duplicate mesh/ARAM archive records.
    public static float BedScale(float depth)
    {
        float radius=CylinderWorld.Radius+WaterSurface.Height;
        if(!float.IsFinite(depth)||depth<=0||depth>=radius)
            throw new ArgumentOutOfRangeException(nameof(depth));
        return (radius-depth)/radius;
    }
    public static float BedAxisOffset(float depth)=>(BedScale(depth)-1)*CylinderWorld.Radius;

    private static void Put(byte[] data,int at,int value)
    {for(int i=0;i<4;i++)data[at+i]=(byte)(value>>(i*8));}
}
